'use strict';
const assert=require('assert'),fs=require('fs'),path=require('path'),http=require('http');
const {chromium,webkit}=require('playwright');
const root=process.env.P1_ROOT||path.resolve(__dirname,'../..'),out=process.env.P1_OUTPUT||path.join(root,'artifacts','explanation-p1');fs.mkdirSync(out,{recursive:true});
const server=http.createServer((req,res)=>{let p=path.join(root,decodeURIComponent(req.url.split('?')[0]));if(p.endsWith('/'))p+='index.html';try{res.setHeader('Content-Type',({'.html':'text/html','.js':'text/javascript','.css':'text/css','.json':'application/json'})[path.extname(p)]||'application/octet-stream');res.end(fs.readFileSync(p));}catch(e){res.statusCode=404;res.end();}});
(async()=>{await new Promise(r=>server.listen(0,'127.0.0.1',r));const url='http://127.0.0.1:'+server.address().port;const results=[];
for(const [engine,type] of [['chromium',chromium],['webkit',webkit]]){const browser=await type.launch({headless:true});try{for(const width of [320,375,390,430,1280]){const context=await browser.newContext({viewport:{width,height:844}});const page=await context.newPage();const errors=[];page.on('pageerror',e=>errors.push(String(e)));await page.goto(url);await page.waitForFunction(()=>window.App?.controller);await page.evaluate(()=>App.ready);
for(const id of ['J001','J035','L031','L005','L050','L044','L001','L002','L003','L037','L038','L039','L046','L047','L048','J017','J050','J100','J145'])for(const state of ['blank','wrong','correct']){const data=await page.evaluate(({id,state})=>{const correct=state==='correct',q=QuestionData[id];let answer=JSON.parse(JSON.stringify(q.answer));if(state==='blank')answer=q.type==='journal'?{debit:[],credit:[]}:{cells:{}};if(state==='wrong'){if(q.type==='journal')answer.debit[0].amount+=1;else{const key=Object.keys(answer.cells)[0];answer.cells[key]=typeof answer.cells[key]==='number'?answer.cells[key]+1:answer.cells[key]==='借方'?'貸方':'借方';}}const score=GradingEngine.grade(q,answer),v=App.controller.view;v.result(q,score,answer);v.show('view-result');return {id,state,correct,gradedCorrect:score.correct,prompt:q.prompt||q.question,text:document.querySelector('#explanation').innerText,domText:document.querySelector('#explanation').textContent,summary:[...document.querySelectorAll('.explanation-summary-item')].map(e=>e.textContent),transfers:[...document.querySelectorAll('.explanation-transfer-card')].map(e=>({from:e.querySelector('.explanation-transfer-from')?.textContent,to:e.querySelector('.explanation-transfer-to strong')?.textContent,value:e.querySelector('.explanation-transfer-to div')?.textContent,text:e.textContent})),profile:document.querySelector('.explanation-route')?.dataset.explanationProfile,sections:[...document.querySelectorAll('.explanation-flow-section')].map(e=>({section:e.dataset.section,text:e.textContent})),width:innerWidth,bodyScroll:document.documentElement.scrollWidth,explanationWidth:document.querySelector('#explanation').getBoundingClientRect().width,overflow:[...document.querySelectorAll('#explanation *')].filter(e=>e.getBoundingClientRect().right>innerWidth+1&&e.getBoundingClientRect().width>0).map(e=>({tag:e.tagName,cls:e.className,right:e.getBoundingClientRect().right})),routeEvidenceCollapsed:!document.querySelector('.explanation-route-evidence')?.open};},{id,state});data.engine=engine;data.pageErrors=[...errors];results.push(data);if(width===390&&state==='wrong'){await page.locator('#explanation').screenshot({path:path.join(out,`${engine}-${width}-${id}-${state}.png`)});}}
await context.close();}}finally{await browser.close();}}
fs.writeFileSync(path.join(out,'render-paths.json'),JSON.stringify(results,null,2));const failures=[];for(const r of results){const t=r.domText,issue=code=>failures.push({engine:r.engine,width:r.width,id:r.id,state:r.state,code});
if(r.gradedCorrect!==r.correct)issue('GRADING_STATE');
if(!r.text.trim())issue('VISIBLE_TEXT_MISSING');
if(r.bodyScroll>r.width+1)issue('DOCUMENT_HORIZONTAL_OVERFLOW');
if(r.pageErrors.length)issue('PAGE_SCRIPT_ERROR');
if(!r.sections.length)issue('STRUCTURED_PATH_MISSING');
const diagnostic=r.sections.filter(x=>x.section==='mistakes').map(x=>x.text).join(' ');
const reviewedGuidance={L001:/期首残高.*増加.*減少/,L002:/期首残高.*増加.*減少/,L003:/期首残高.*増加.*減少/,L037:/相手勘定[\s\S]*残高方向/,L038:/相手勘定[\s\S]*残高方向/,L039:/再振替[\s\S]*月数[\s\S]*損益[\s\S]*次期繰越/,L046:/支払.*費用.*分類[\s\S]*補給/,L047:/総仕入高.*返品.*差し引.*純仕入高/,L048:/総売上高.*返品.*差し引.*純売上高/}[r.id];
if(r.state!=='correct'&&reviewedGuidance&&!reviewedGuidance.test(diagnostic))issue('REVIEW_FORMAT_GUIDANCE');
const special={J017:[['現金過不足','原因判明まで記録する仮勘定','借方','5,000']],J050:[['損益','一時的な決算勘定','借方','420,000'],['繰越利益剰余金','会社内に留保された純資産','貸方','420,000']],J100:[['損益','一時的な決算勘定','借方','430,000'],['繰越利益剰余金','会社内に留保された純資産','貸方','430,000']],J145:[['貸倒引当金','資産の評価勘定','貸方','10,400']]}[r.id]||[];
const transactionReason={現金過不足:/実際有高[\s\S]*不足額[\s\S]*借方に仮記入/,損益:/貸方残高[\s\S]*当期純利益[\s\S]*締め切る[\s\S]*借方に記入/,繰越利益剰余金:/当期純利益[\s\S]*蓄積した利益[\s\S]*純資産[\s\S]*貸方に記入/,貸倒引当金:/必要額[\s\S]*整理前[\s\S]*不足する差額[\s\S]*貸方に追加/};
for(const [account,definition,side,amount] of special)if(!r.transfers.some(card=>card.from.includes(account+'：')&&card.from.includes(definition)&&card.from.includes(side+'に')&&transactionReason[account].test(card.from)&&!card.from.includes('特殊勘定の増加・減少')&&!card.from.includes(amount+'円')&&card.to===side&&card.value.includes(amount)))issue('REVIEW_SPECIAL_ACCOUNT_REASON');

if(/取り違えています|勘違いしています/.test(diagnostic))issue('UNSUPPORTED_CAUSE_DIAGNOSIS');
if(r.state!=='correct'){
const guidance={L031:/資産の増加は借方[^。]*減少は貸方[^。]*。負債の増加は貸方[^。]*減少は借方/,L005:/取得原価[^。]*耐用年数[\s\S]*減価償却累計額[\s\S]*帳簿価額/,L050:/現金が増える[^。]*入金伝票[^。]*現金が減る[^。]*出金伝票[^。]*現金が動かない[^。]*振替伝票/,L044:/入金は加算、出金は減算して直前残高/}[r.id];
if(guidance&&!guidance.test(diagnostic))issue('FORMAT_GUIDANCE_MISSING');
}
if(['L031','L005','L050'].includes(r.id)&&r.state!=='correct'&&/入金は加算、出金は減算して直前残高/.test(t))failures.push({engine:r.engine,width:r.width,id:r.id,state:r.state,code:'P1_A_WRONG_FORMAT'});if(['J001','J035'].includes(r.id)){const summary=r.summary.join(' '),cards=r.transfers;const expected=r.id==='J001'?[['現金','資産','増加','借方','3,000,000'],['資本金','純資産','増加','貸方','3,000,000']]:[['貯蔵品','資産','増加','借方','5,000'],['租税公課','費用','減少','貸方','5,000']];for(const [account,nature,motion,side,amount] of expected){const relation=new RegExp((nature==='資産'?'(?<!純)資産':nature)+'の'+motion+'[^。]{0,30}'+side);if(!cards.some(card=>card.from.includes(account)&&relation.test(card.from)&&card.to===side&&card.value.includes(amount)))failures.push({engine:r.engine,width:r.width,id:r.id,state:r.state,code:'P1_B_CARD_CAUSAL_RELATION',account});}const reasoning=r.id==='J001'?/受け取った現金[^。]*資産の増加/.test(summary)&&/株主[^。]*純資産[^。]*資本金[^。]*増加/.test(summary):/未使用分[^。]*次期以降[^。]*資産/.test(summary)&&/租税公課[^。]*取り崩[^。]*貯蔵品[^。]*振り替/.test(summary);if(!reasoning)failures.push({engine:r.engine,width:r.width,id:r.id,state:r.state,code:'P1_B_FACT_REASON'});const repeated=r.summary.filter(x=>r.id==='J001'?/株主[^。]*純資産[^。]*資本金/.test(x):/未使用分[^。]*次期以降[^。]*資産/.test(x)).length;if(repeated>1)failures.push({engine:r.engine,width:r.width,id:r.id,state:r.state,code:'P1_B_DUPLICATE_FACT_REASON'});}}fs.writeFileSync(path.join(out,'failures.json'),JSON.stringify(failures,null,2));process.exitCode=failures.length?1:0;console.log(JSON.stringify({failures:failures.length,cases:results.length,gradedAsExpected:results.filter(x=>x.id!=='epilogue').every(x=>x.gradedCorrect===x.correct),overflowCases:results.filter(x=>x.bodyScroll>x.width).map(x=>[x.engine,x.width,x.id,x.correct]),errors:results.flatMap(x=>x.pageErrors||[])}));server.close();assert.strictEqual(failures.length,0,'P1 rendered semantic/visibility gates must all pass');})().catch(e=>{console.error(e);server.close();process.exitCode=1;});
